import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
/* eslint-disable */
// Imports
import UserTeams from "@/components/Teams/UserTeams.vue";
import TeamBulkupload from "@/components/DialogsList/TeamBulkupload.vue";
import AddMember from "@/components/StaticForms/AddMember.vue";
import ApprovalsList from "@/components/SettingsDialogs/ApprovalsList.vue";
import ProfileConfig from "@/components/SettingsDialogs/ProfileConfig.vue";
import MemberConfig from "@/components/SettingsDialogs/MemberConfig.vue";
import TeamVisibility from "@/components/SettingsDialogs/TeamVisibility.vue";
import AllTeams from "@/components/Teams/AllTeams.vue";
import BulkTeamImport from "@/components/Teams/BulkTeamImport.vue";
import { my_team_user_list } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import AddUser from "@/components/UserDialogs/AddUser.vue";
import SnackBar from "@/components/SnackBar.vue";
import { export_users } from "@/graphql/mutations.js";
const FileSaver = require("file-saver");
import * as XLSX from "xlsx";
import axios from "axios";
import html2canvas from "html2canvas";
import CreateExternalTicketDialog from "../Tickets/CreateExternalTicketDialog.vue";
// import { get_current_details } from "@/mixins/GetCuurentUser.js";
import ReportiesList from "./ReportiesList.vue";
export default {
  // Components
  components: {
    AddUser,
    SnackBar,
    AddMember,
    AllTeams,
    TeamBulkupload,
    TeamVisibility,
    MemberConfig,
    ProfileConfig,
    ApprovalsList,
    BulkTeamImport,
    UserTeams,
    CreateExternalTicketDialog,
    ReportiesList
  },
  // mixins: [get_current_details],
  // Data
  data() {
    return {
      // Array properties
      headers: [{
        text: "Profile",
        value: "user_profile_pic_url",
        sortable: false
      }, {
        text: "Name",
        value: "full_user_name",
        sortable: false
      }, {
        text: "Member ID",
        value: "member_id",
        sortable: false
      }, {
        text: "Mobile Number",
        value: "user_contact_number",
        sortable: false
      }, {
        text: "Group",
        value: "department",
        sortable: false
      }, {
        text: "Location",
        value: "location",
        sortable: false
      }, {
        text: "Reporting Manager",
        value: "reporting_manager",
        sortable: false
      }, {
        text: "Status",
        value: "user_status",
        sortable: false
      }],
      tableData: [],
      excelHeaders: [],
      excelTableData: [],
      // Object properties
      SnackBarComponent: {},
      pagination: {
        itemsPerPage: 20,
        page: 1
      },
      // String properties
      search: "",
      searchValue: "",
      toggle_exclusive: "myteams",
      defaultStatus: "ACTIVE",
      groupName: "",
      locationName: "",
      // Boolean properties
      addmember: false,
      dropExceldailog: false,
      exportload: false,
      tableLoading: false,
      fixed: true,
      adminAppExists: false,
      showFilterDrawer: false,
      // Number properties
      componentCheck: 0,
      cardHeight: 0,
      height: 0,
      activeFiltersCount: 0,
      // Null properties
      next_token: null,
      //Screenshot Values
      DialogCreateExternalTicket: false,
      ScreenshotFile: null,
      orgDetails: {
        bucket_name: "stichh-medias",
        region: "us-east-1"
      }
    };
  },
  // Lifecycle hooks
  created() {
    // this.get_current_details();
    this.fetch_admin_apps();
    this.get_my_team();
    this.height = window.innerHeight - 290;
  },
  mounted() {
    this.cardHeight = window.innerHeight - 140;
  },
  // Watchers
  watch: {
    toggle_exclusive() {
      this.addmember = false;
    },
    search() {
      if (this.search != "") {
        if (this.search.length >= 3) {
          this.get_my_team();
        }
      } else {
        this.get_my_team();
      }
    }
  },
  // Computed properties
  computed: {
    totalMembers() {
      return this.tableData.length || 0;
    }
  },
  // Methods
  methods: {
    // Filter methods
    openFilterDrawer() {
      // console.log('openFilterDrawer called');
      this.showFilterDrawer = true;
    },
    closeFilterDrawer() {
      this.showFilterDrawer = false;
    },
    handleActiveFiltersCount(count) {
      this.activeFiltersCount = count;
    },
    handleSearchChange(value) {
      // console.log('Search changed:', value);
      this.searchValue = value;
      // The child component will handle the search through the prop watcher
    },
    handleFilterClick() {
      // console.log('handleFilterClick called');
      if (this.$refs.allTeamsRef) {
        this.$refs.allTeamsRef.openFilterDrawer();
      }
    },
    // Admin methods
    fetch_admin_apps() {
      const userObj = this.$store.getters.GetUserObj;
      if (userObj.user.user_type == "ADMIN" || userObj.user.user_type == "OWNER") {
        this.adminAppExists = true;
      }
    },
    // Data fetching methods
    async get_my_team() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(my_team_user_list, {
          input: {
            organization_id: data.organization.organization_id,
            user_email_id: data.user.user_email_id,
            limit: this.search != "" ? 1000 : 100,
            name_search: this.search,
            nextToken: this.search != "" ? null : this.next_token
          }
        }));
        this.tableLoading = false;
        var dataArray = [];
        var response = JSON.parse(result.data.my_team_user_list);
        this.next_token = response.nextToken;
        if (response.Status == "SUCCESS") {
          dataArray = response.user || [];

          // Ensure dataArray is an array and filter out any invalid items
          if (Array.isArray(dataArray)) {
            dataArray = dataArray.filter(item => item && item.user_id);
          } else {
            dataArray = [];
          }
          let array = this.tableData.concat(dataArray);
          this.tableData = array;
          const uniqueArrayOfObjects = this.tableData.filter((obj, index, self) => {
            // Check if obj exists and has user_id property
            if (!obj || !obj.user_id) return false;
            return index === self.findIndex(o => o && o.user_id && o.user_id === obj.user_id);
          });
          this.tableData = uniqueArrayOfObjects;
        }
      } catch (error) {
        console.log(error);
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    get_myteam_Pagination() {
      if (this.next_token) {
        this.get_my_team();
      }
    },
    // Export and download methods
    async export_members() {
      this.addmember = false;
      this.exportload = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(export_users, {
          input: {
            organization_id: data.organization.organization_id,
            user_status: this.defaultStatus,
            department_name: this.groupName == "" ? undefined : this.groupName,
            location_name: this.locationName == "" ? undefined : this.locationName
          }
        }));
        var response = JSON.parse(result.data.export_users);
        if (response.Status == "SUCCESS") {
          this.download_invoice(response.url);
          this.groupName = "";
          this.locationName = "";
        } else {
          this.exportload = false;
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
          this.groupName = "";
          this.locationName = "";
        }
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
        this.exportload = false;
      }
    },
    async download_invoice(url) {
      this.exportload = false;
      let firstName = this.$store.getters.GetUserObj?.organization?.organization_team_id;
      let fileName = firstName ? firstName + "_" + "Members" + ".xlsx" : "_" + "Members" + ".xlsx";
      axios({
        url: url,
        method: "GET",
        responseType: "blob"
      }).then(response => {
        const blob = new Blob([response.data], {
          type: response.headers["content-type"]
        });
        FileSaver.saveAs(blob, fileName);
      }).catch(error => {
        console.error("Error downloading the file:", error);
      });
    },
    download_item() {
      try {
        // console.log('Download template clicked');
        const headers = ["First Name*", "Last Name", "Email ID*", "Member ID", "Country Code", "Contact Number"];
        let firstName = this.$store.getters.GetUserObj?.organization?.organization_team_id || "";
        let fileName = firstName ? `${firstName}_Members Template.xlsx` : `Members Template.xlsx`;

        // console.log('Creating Excel file:', fileName);
        const ws = XLSX.utils.aoa_to_sheet([headers]);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, "Sheet1");
        XLSX.writeFile(wb, fileName);

        // console.log('Excel file created successfully');
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "green",
          SnackbarText: "Template downloaded successfully!",
          timeout: 3000,
          Top: true
        };
      } catch (error) {
        console.error("Error downloading template:", error);
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Error downloading template: " + error.message,
          timeout: 5000,
          Top: true
        };
      }
    },
    // UI interaction methods
    add_members() {
      this.addmember = false;
      this.addmember = true;
    },
    back_call() {
      this.$router.push("/home/UserTeams");
    },
    add_data() {
      this.componentCheck = 1;
      this.addDialog = true;
    },
    close_dialog(val) {
      if (val == 0) {
        this.addDialog = false;
      } else if (val == 1) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Please Provide Details",
          timeout: 5000,
          Top: true
        };
      } else if (val == 2) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Invalid Email",
          timeout: 5000,
          Top: true
        };
      } else if (val == 3) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "green",
          SnackbarText: "User Created Successfully",
          timeout: 5000,
          Top: true
        };
        this.addDialog = false;
      }
    },
    // Event handler methods
    handleDownloadTemplate() {
      // console.log('Download template handler called');
      this.download_item();
    },
    handleSuccess({
      results,
      header
    }) {
      this.excelTableData = results;
      this.componentCheck = 2;
      this.excelHeaders = header;
      this.dropExceldailog = true;
    },
    beforeUpload(file) {
      const isLt1M = file.size / 1024 / 1024 < 1;
      if (isLt1M) {
        return true;
      }
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "warning",
        SnackbarText: "Please do not upload files larger than 1MB in size.",
        timeout: 5000,
        Top: true
      };
      return false;
    },
    selected_data(val) {
      this.defaultStatus = val;
    },
    group_name(val) {
      this.groupName = "";
      this.groupName = val;
    },
    location_name(val) {
      this.locationName = "";
      this.locationName = val;
    },
    // Utility methods
    get_user_id(val) {
      for (var i = 0; i < this.tableData.length; i++) {
        if (val == this.tableData[i].user_id) {
          return this.tableData[i].full_user_name;
        }
      }
    },
    update_user() {
      // Placeholder for user update functionality
    },
    // Notification methods
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.addDialog = false;
      this.addmember = false;
      this.dropExceldailog = false;
      this.tableData = [];
      this.get_my_team();
    },
    async TakeScreenshot() {
      const target = document.body;
      const canvas = await html2canvas(target, {
        scale: window.devicePixelRatio || 2,
        useCORS: true,
        logging: false,
        windowWidth: document.documentElement.scrollWidth,
        windowHeight: document.documentElement.scrollHeight
      });
      const dataUrl = canvas.toDataURL("image/png");
      const blob = await (await fetch(dataUrl)).blob();
      const file = new File([blob], "screenshot.png", {
        type: "image/png"
      });
      this.ScreenshotFile = file;
      this.DialogCreateExternalTicket = true;
    },
    DialogCreateExternalTicketEmit() {
      this.DialogCreateExternalTicket = false;
    }
  }
};
